  triggers: [
    {
      id: "arrive",
      x: 56,
      y: 0,
      w: 24,
      h: 13,
      text: "Gull Stilts: a village on legs, standing in the sea. Houses of tin and pallet and car doors on posts driven into a drowned town's streets, boardwalks for streets, boats for carts, and under the boards, a yard down in green water, the tops of street lamps. The water has a skin on it like a bruise, purple and gold where the light catches it, and the smell of the village is fish, smoke and something under both that belongs in an engine.",
      effects: [
        {
          learn: "seen_stilts"
        },
        {
          set: "ds_open"
        },
        {
          lead: "l_ds_sheen"
        },
        {
          quest: "q_ds_sheen",
          start: true
        }
      ]
    },
    {
      id: "ebb",
      x: 35,
      y: 50,
      w: 9,
      h: 6,
      if: {
        not: {
          flag: "ds_lua_met"
        }
      },
      text: "The Ebb Steps: the broad steps of some drowned hall going down into the water, and half the village on them. A small shape in a weighted net lies on the bottom step with the tide going out over its feet. A woman kneels by it with her hands flat on the net, not crying. Nobody speaks. A man begins to say a name and stops when she looks at him.",
      effects: [
        {
          learn: "ds_burial_seen"
        }
      ]
    },
    {
      id: "greta",
      x: 11,
      y: 19,
      w: 19,
      h: 7,
      text: "The Greta: a car ferry from before the Burn, run aground in the middle of the village and never refloated, her car deck open to the sky. Benches where the cars stood. At the bow end, under two lamps, a chart table with a book on it as thick as a brick, and an old woman who looks up from it as if she knew you were coming aboard.",
      effects: [
        {
          learn: "ds_greta_seen"
        }
      ]
    },
    {
      id: "post",
      x: 34,
      y: 25,
      w: 2,
      h: 3,
      text: "A steel container on a pontoon, lashed to the Greta's stern, painted in the guild's colours under the rust: the tide post. SALT \u2014 TWINE \u2014 MEDICINE \u2014 FISH BOUGHT. A man in a good coat behind the counter, writing.",
      effects: [
        {
          learn: "ds_post_seen"
        }
      ]
    },
    {
      id: "jesty",
      x: 7,
      y: 46,
      w: 13,
      h: 9,
      text: "The Jesty: a drowned hotel's roof, the only thing in the bay taller than the stilts, with its parapet a hand above the water at high tide. Against its south edge a guild barge lies broken-backed where it struck, her hold open, divers going in and out of it like gulls at a gutted fish.",
      effects: [
        {
          learn: "ds_jesty_seen"
        },
        {
          quest: "q_ds_light",
          start: true
        }
      ]
    },
    {
      id: "stage",
      x: 54,
      y: 45,
      w: 13,
      h: 6,
      text: "Coker's dive stage: a grate platform with a hand-cranked air pump on it, a coil of hose as thick as a wrist, ladders going down into the green, and a woman counting under her breath with her eyes on a line in the water.",
      effects: [
        {
          learn: "ds_stage_seen"
        }
      ]
    }
  ],
